WITH flattened_attrs AS (SELECT id, host, level, latency_ms, payload_json, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, COALESCE(context['version'], 'none') AS version_or_default, SHIFTRIGHT(status_code, 2) AS status_code_high, context['region'] AS region, SIZE(context) AS num_context FROM app_logs) SELECT level, COUNT_IF(level = 'ERROR') AS error_events, SUM(CASE WHEN host = 'h1' THEN status_code_high ELSE 0 END) AS h1_status_code_high, AVG(duration_sec) FILTER (WHERE host = 'h1') AS h1_avg_duration_sec FROM flattened_attrs GROUP BY level;
